/**
 * Splits the full catalogue (src/data/catalogue-source.ts, the source of truth) into:
 *   - src/data/products.ts         light records bundled with the app (cards, filters, menus)
 *   - src/data/products-detail.ts  heavy fields (description, features, photos, variants), loaded on demand
 * Runs at the start of every build. Edit catalogue-source.ts, never the two generated files.
 */
import fs from 'node:fs';
import { PRODUCTS, CATEGORIES_WITH_SUBCATEGORIES } from '../src/data/catalogue-source';

const light = (PRODUCTS as any[]).map((p) => {
  const { description, keyFeatures, images, variants, ...rest } = p;
  const first = variants?.length ? (variants.find((v: any) => v.available) ?? variants[0]) : undefined;
  return {
    ...rest,
    ...(first?.image && first.image !== rest.imageUrl ? { heroImage: first.image } : {}),
    ...(images?.length > 1 ? { photoCount: images.length } : {}),
    description: '',
    keyFeatures: [],
    // Cards only need to know whether options exist, what prices vary and whether anything is in stock.
    ...(variants?.length ? { variants: variants.map((v: any) => ({ id: '', title: '', options: [], price: v.price, available: v.available })) } : {}),
  };
});

const detail: Record<string, any> = {};
for (const p of PRODUCTS as any[]) {
  detail[p.id] = { description: p.description, keyFeatures: p.keyFeatures, ...(p.images ? { images: p.images } : {}), ...(p.variants ? { variants: p.variants } : {}) };
}

// One tiny file per product, fetched by the product page instead of the whole details bundle.
fs.mkdirSync('public/data/p', { recursive: true });
for (const [id, d] of Object.entries(detail)) fs.writeFileSync(`public/data/p/${id}.json`, JSON.stringify(d));

const header = '// GENERATED by scripts/split-catalogue.ts from catalogue-source.ts. Do not edit.\n';
fs.writeFileSync(
  'src/data/products.ts',
  `${header}import { Product } from '../types';\n\nexport const PRODUCTS: Product[] = ${JSON.stringify(light)};\n\nexport const CATEGORIES_WITH_SUBCATEGORIES: { category: string; description: string; subcategories: string[] }[] = ${JSON.stringify(CATEGORIES_WITH_SUBCATEGORIES)};\n`,
);
fs.writeFileSync(
  'src/data/products-detail.ts',
  `${header}import { ProductVariant } from '../types';\n\nexport interface ProductDetail { description: string; keyFeatures: string[]; images?: string[]; variants?: ProductVariant[] }\n\nexport const DETAILS: Record<string, ProductDetail> = ${JSON.stringify(detail)};\n`,
);
const kb = (f: string) => Math.round(fs.statSync(f).size / 1024);
console.log(`catalogue split: products.ts ${kb('src/data/products.ts')} KB, products-detail.ts ${kb('src/data/products-detail.ts')} KB`);
